<script module lang="ts">
/**
 * One turn of a conversation (`design/components/chat-message.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/chat-message.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { Icon, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/chat-message.module.css'
import Avatar from '../structure/Avatar.svelte'

export type ChatMessageStatus = NonNullable<ChatMessageProps['status']>

export type ChatRole = NonNullable<ChatMessageProps['role']>

export interface ChatMessageProps {
  /**
   * The hover row of `ghost/neutral/sm iconOnly` Buttons, such as copy, regenerate and helpful.
   */
  actions?: Snippet
  /**
   * The speaker's name, used as the article's accessible name and first in the meta row.
   */
  author: string
  /**
   * The speaker's picture, replaced by the reader's initials or the model's mark when absent.
   */
  avatar?: string
  /**
   * The turn's content, in reading order.
   */
  children: Snippet
  /**
   * The speaker's role, which sets the layout and is the only frame choice the caller makes.
   */
  role: 'user' | 'system' | 'assistant'
  /**
   * The turn's status, where `complete` is the rest state and sets no attribute.
   */
  status?: 'error' | 'streaming' | 'complete' | 'stopped'
  /**
   * The app's text for `stopped` or `error`, such as "Stopped" or "Something went wrong".
   */
  statusMessage?: string
  /**
   * The time, preformatted by the app (Timeline's rule for time).
   */
  time?: string
}
</script>

<script lang="ts">
let {
  actions,
  author,
  avatar,
  children,
  role,
  status = 'complete',
  statusMessage,
  time,
}: ChatMessageProps = $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get actions() {
    return actions
  },
  get default() {
    return children
  },
}
</script>

{@render joined.start?.()
}{#if joined.shown
  }<article
    class={styles.message}
    data-role={role}
    data-status={status === 'complete' ? undefined : status}
    aria-label={author}
    aria-busy={(status === 'streaming') ? true : undefined}
    data-member="chat-message"
    >{#if role !== 'system'
      }<span class={styles.mark}
        >{#if role === 'assistant' && avatar === undefined
          }<span class={styles.model} aria-hidden="true"><Icon name="model" size="sm" /></span
        >{:else
          }<Avatar name={author} src={avatar} size="md"
        />{/if
      }</span
    >{/if
    }<div class={styles.body}
      >{#if role !== 'system'
        }<div class={styles.meta}
          ><span class={styles.author}>{author}</span
          >{#if time !== undefined}<span class={styles.time}>{time}</span>{/if
        }</div
      >{/if
      }<div class={styles.content}>{@render children?.()}</div
      >{#if (status === 'stopped' || status === 'error') && statusMessage !== undefined
        }<p class={styles.notice}
          ><span class={styles.noticeGlyph}
            ><Icon name={status === 'error' ? 'error' : 'warning'} size="sm"
          /></span
          >{statusMessage
        }</p
      >{/if
      }{#if slots.actions}<div class={styles.actions}>{@render actions?.()}</div>{/if
    }</div
  ></article
>{/if
}{@render joined.end?.()}
